import os

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

SECRET_KEYS = {"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"}


def parse_dotenv_line(line):
    """Return (key, value) for an assignment line, or None for blanks, comments and non-assignments."""
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    if line.startswith("export") and line[len("export"):len("export") + 1].isspace():
        line = line[len("export"):].lstrip()
    if "=" not in line:
        return None
    key, value = line.split("=", 1)
    key = key.strip()
    value = value.strip()
    if value[:1] in ("'", '"'):
        # Quoted: take everything up to the matching closing quote; anything after it is ignored.
        end = value.find(value[0], 1)
        value = value[1:end] if end != -1 else value[1:]
    if not key:
        return None
    return key, value


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            parsed = parse_dotenv_line(line)
            if parsed is not None:
                key, value = parsed
                values[key] = value
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config

